codeExamples.java:
public class Main {
    public static void main(String[] args) {
        String text = "Hello World";
        String upperText = text.toUpperCase();
        String[] splitWords = text.split(" ");
        System.out.println("Upper: " + upperText + ", Word Count: " + splitWords.length);
    }
}

codeExamples.javascript:
let text = 'Hello World';
let upperText = text.toUpperCase();
let splitWords = text.split(' ');
let joinedText = splitWords.join('-');
console.log(`Upper: ${upperText}, Words: ${splitWords}, Joined: ${joinedText}`);

codeExamples.cpp:
#include <iostream>
#include <string>
#include <algorithm>
int main() {
    std::string text = "Hello World";
    std::transform(text.begin(), text.end(), text.begin(), ::toupper);
    std::cout << "Upper: " << text << std::endl;
    return 0;
}
